package com.yonlab.vision;
import android.content.Context;import android.graphics.*;import android.os.SystemClock;import org.json.*;import java.util.*;
import org.opencv.android.*;import org.opencv.core.Mat;import org.opencv.imgproc.Imgproc;import org.opencv.objdetect.*;

/** Distinct real OpenCV QR locators. No neural weights or invented confidence scores. */
final class AddedQrRunner {
 private static final Object LOCK=new Object();private static QRCodeDetector normal;private static QRCodeDetectorAruco aruco;
 static OneModelRunner.Result run(Context c,String id,Bitmap input,OneModelRunner.Cancel cancel){OneModelRunner.Result out=new OneModelRunner.Result("qr",id);long started=SystemClock.elapsedRealtime();Mat rgba=null,gray=null,points=null;
  try{ExpansionImageRunner.check(cancel);if(!OpenCVLoader.initLocal())throw new java.io.IOException("QR 이미지 엔진을 준비하지 못했습니다");rgba=new Mat();gray=new Mat();points=new Mat();long load=SystemClock.elapsedRealtime();List<String> values=new ArrayList<>();synchronized(LOCK){GraphicalCodeDetector detector;if("opencv-qr-aruco".equals(id)){if(aruco==null)aruco=new QRCodeDetectorAruco();detector=aruco;}else{if(normal==null)normal=new QRCodeDetector();detector=normal;}out.loadMs=SystemClock.elapsedRealtime()-load;long infer=SystemClock.elapsedRealtime();Utils.bitmapToMat(input,rgba);Imgproc.cvtColor(rgba,gray,Imgproc.COLOR_RGBA2GRAY);detector.detectAndDecodeMulti(gray,values,points);out.inferenceMs=SystemClock.elapsedRealtime()-infer;}
   ExpansionImageRunner.check(cancel);out.image=input.copy(Bitmap.Config.ARGB_8888,true);if(out.image==null)throw new java.io.IOException("QR 사진을 준비하지 못했습니다");Canvas canvas=new Canvas(out.image);Paint paint=new Paint(3);paint.setStyle(Paint.Style.STROKE);paint.setColor(Ui.ACCENT);paint.setStrokeWidth(Math.max(2,input.getWidth()/260f));JSONArray codes=new JSONArray();StringBuilder text=new StringBuilder();for(int i=0;i<values.size();i++){String value=values.get(i);if(value==null||value.isEmpty())continue;codes.put(new JSONObject().put("format","QR_CODE").put("value",value));if(text.length()>0)text.append('\n');text.append(value);if(points.rows()>i&&points.cols()>=4){Path polygon=new Path();for(int k=0;k<4;k++){double[] p=points.get(i,k);if(p==null||p.length<2)continue;if(k==0)polygon.moveTo((float)p[0],(float)p[1]);else polygon.lineTo((float)p[0],(float)p[1]);}polygon.close();canvas.drawPath(polygon,paint);}}
   out.metrics.put("codes",codes).put("characters",text.length()).put("engine",id).put("implementation","OpenCV 4.13.0").put("trainedModel",false).put("nativeCache","one detector per locator per process; input Mats released per call");out.summary=codes.length()==0?"코드 없음":"QR_CODE · "+codes.length()+"개";out.detail=text.toString();out.state="COMPLETED";
  }catch(Exception|LinkageError|OutOfMemoryError e){out.state=cancel.canceled()?"CANCELED":"ERROR";out.errorType=e.getClass().getSimpleName();out.summary="CANCELED".equals(out.state)?"분석 취소":"다른 인식 엔진으로 다시 분석하세요";}
  finally{if(points!=null)points.release();if(gray!=null)gray.release();if(rgba!=null)rgba.release();out.engineCreated=false;out.engineCloseReturned=true;out.elapsedMs=SystemClock.elapsedRealtime()-started;}return out;
 }
}
